/* Z EX — shared helpers for the background scenes (no assets, no DOM access).
   Loaded before every scene file and before hands_bg.js. */
(function () {
  'use strict';
  var U = window.ZEX_UTIL = window.ZEX_UTIL || {};

  U.snap = function (v, g) { return Math.round(v / g) * g; };
  U.clamp01 = function (x) { return x < 0 ? 0 : (x > 1 ? 1 : x); };
  U.smooth = function (x) { x = x < 0 ? 0 : (x > 1 ? 1 : x); return x * x * (3 - 2 * x); };
  // alpha (0..1) → index into opts.ia / opts.ga colour tables (41 steps, no string building per frame)
  U.q = function (a) { a = a < 0 ? 0 : (a > 1 ? 1 : a); return (a * 40 + 0.5) | 0; };
  // tiny seeded RNG → same layout on every open
  U.rng = function (seed) {
    var s = seed;
    return function () { s = (s * 16807) % 2147483647; return (s - 1) / 2147483646; };
  };

  /* ── Pixel "Z" (5 x 7 bitmap) with a soft gold halo ── */
  var ZB = ['11111', '00001', '00010', '00100', '01000', '10000', '11111'];
  var ZC = [], ZR = [];
  ZB.forEach(function (row, r) {
    for (var c = 0; c < 5; c++) if (row.charAt(c) === '1') { ZC.push(c); ZR.push(r); }
  });
  U.Z_COLS = ZC; U.Z_ROWS = ZR;

  // cx,cy = centre · c = cell size in px · a = overall alpha 0..1
  U.drawZ = function (ctx, o, cx, cy, c, t, a) {
    if (a <= 0.01) return;
    var n = ZC.length, q = U.q, ga = o.ga, i, al;
    ctx.fillStyle = ga[q(0.05 * a)];
    ctx.beginPath(); ctx.arc(cx, cy, c * 6.5, 0, 6.2832); ctx.fill();
    ctx.fillStyle = ga[q(0.09 * a)];
    ctx.beginPath(); ctx.arc(cx, cy, c * 4, 0, 6.2832); ctx.fill();
    var w = c >= 4 ? c - 1 : c;
    for (i = 0; i < n; i++) {
      al = a * (0.72 + 0.28 * Math.sin(t * 2.6 + i * 0.9));
      ctx.fillStyle = ga[q(al)];
      ctx.fillRect(Math.round(cx + (ZC[i] - 2.5) * c), Math.round(cy + (ZR[i] - 3.5) * c), w, w);
    }
