  /* ── Dot-matrix eye ──
     ex,ey centre · e half-width in px · open 0..1 · flip ±1 (mirror) · a alpha
     mode 0 = 4-point gold star pupil, 1 = pixel Z pupil · lx,ly gaze −1..1 */
  function inLid(x, y, open) {
    var s = 1 - x * x;
    if (s <= 0) return false;
    var tl = -0.12 * x;
    return y > tl - 0.52 * open * Math.pow(s, 0.75) + 0.04 && y < tl + 0.34 * open * s - 0.03;
  }
  U.drawEye = function (ctx, o, ex, ey, e, open, flip, t, a, mode, lx, ly) {
    if (a <= 0.01) return;
    var g = o.g, ia = o.ia, ga = o.ga, q = U.q, M = 24, i, x, s, yu, yl, tl, gx, gy, ix, iy;
    if (open < 0.04) {                                    // closed: a flat dotted lid line
      ctx.fillStyle = ia[q(0.8 * a)];
      for (i = 0; i <= M; i++) {
        x = -1 + 2 * i / M;
        ctx.fillRect(Math.round(ex + x * e * flip), Math.round(ey - 0.12 * x * e), g, g);
      }
      return;
    }
    // upper lid (bright) + lower lid (dim)
    ctx.fillStyle = ia[q(0.9 * a)];
    for (i = 0; i <= M; i++) {
      x = -1 + 2 * i / M; s = 1 - x * x; tl = -0.12 * x;
      yu = tl - 0.52 * open * Math.pow(s, 0.75);
      ctx.fillRect(Math.round(ex + x * e * flip), Math.round(ey + yu * e), g, g);
    }
    ctx.fillStyle = ia[q(0.55 * a)];
    for (i = 1; i < M; i++) {
      x = -1 + 2 * i / M; s = 1 - x * x; tl = -0.12 * x;
      yl = tl + 0.34 * open * s;
      ctx.fillRect(Math.round(ex + x * e * flip), Math.round(ey + yl * e), g, g);
    }
    // lashes
    ctx.beginPath();
    for (i = 4; i < M - 1; i += 2) {
      x = -1 + 2 * i / M; s = 1 - x * x; tl = -0.12 * x;
      yu = tl - 0.52 * open * Math.pow(s, 0.75);
      ctx.moveTo(ex + x * e * flip, ey + yu * e);
