    ctx.fillStyle = ia[q(0.3 * a)];
    for (iy = 0; iy < 9; iy++) {
      gy = -0.5 + iy * 0.105;
      for (ix = 0; ix < 17; ix++) {
        if (((ix * 7 + iy * 13) & 3) === 0) continue;
        gx = -0.9 + ix * 0.1125;
        if (!inLid(gx, gy, open)) continue;
        if ((gx - icx) * (gx - icx) + (gy - icy) * (gy - icy) < (ir + 0.05) * (ir + 0.05)) continue;
        ctx.fillRect(Math.round(ex + gx * e * flip), Math.round(ey + gy * e), g, g);
