    // iris rings
    ctx.fillStyle = ia[q(0.85 * a)];
    for (i = 0; i < 22; i++) {
      gx = icx + Math.cos(i * 0.2856) * ir; gy = icy + Math.sin(i * 0.2856) * ir;
      if (inLid(gx, gy, open)) ctx.fillRect(Math.round(ex + gx * e * flip), Math.round(ey + gy * e), g, g);
    }
    ctx.fillStyle = ia[q(0.45 * a)];
    for (i = 0; i < 14; i++) {
      gx = icx + Math.cos(i * 0.4488) * ir * 0.64; gy = icy + Math.sin(i * 0.4488) * ir * 0.64;
      if (inLid(gx, gy, open)) ctx.fillRect(Math.round(ex + gx * e * flip), Math.round(ey + gy * e), g, g);
    }
