      ctx.moveTo(px, py - L); ctx.lineTo(px + w, py); ctx.lineTo(px, py + L); ctx.lineTo(px - w, py); ctx.closePath();
      ctx.moveTo(px - L2, py); ctx.lineTo(px, py + w * 0.9); ctx.lineTo(px + L2, py); ctx.lineTo(px, py - w * 0.9); ctx.closePath();
      ctx.fill();
      ctx.fillRect(Math.round(px - g), Math.round(py - g), g * 2, g * 2);
    }
  };
})();

